def format_noneng_magnitude(token_id: str, magnitude: float) -> str:
    decimals = NONENG_MAGNITUDE_DECIMALS[token_id]
    if decimals == 0:
        return str(int(round(magnitude)))
    return f"{magnitude:.{decimals}f}"


